'use strict';
const $=s=>document.querySelector(s);
let experiment;
const format=t=>t<.01?t.toFixed(4):t<1?t.toFixed(3):t.toFixed(2);
const colors={classical:['#3d836d','#82ad90','#b6ccaa'],quantum:['#b9a9ce','#8e75b4','#d8cde4']};
const explanations={classical:['Compute exact depot tours for every capacity-feasible customer subset using Held–Karp dynamic programming.','Reuse subset costs in a partition dynamic program to find the globally shortest plan using at most four vehicles.','Check that every city is served once and that each vehicle stays within capacity.'],quantum:['Fit physical atom coordinates to the desired pairwise penalties. This is classical numerical optimization.','On the CPU, solve the quantum evolution and sample bitstrings. No real quantum processor is used here.','Reject illegal assignments, choose a feasible clustering, quantum-route eligible clusters, and compute labeled classical fallback tours.']};
function bars(){const max=Math.max(...Object.values(experiment.summary).map(s=>s.seconds));for(const name of ['classical','quantum']){const s=experiment.summary[name];const bar=$('#'+name+'-bar');bar.style.width=s.seconds/max*100+'%';bar.innerHTML=$('#breakdown').checked?s.stages.map((x,i)=>`<i style="width:${x.seconds/s.seconds*100}%;background:${colors[name][i]}" title="${x.label}: ${format(x.seconds)} s"></i>`).join(''):''}$('#step-times').hidden=!$('#breakdown').checked;$('#step-times').innerHTML=['classical','quantum'].map(name=>'<div>'+experiment.summary[name].stages.map((x,i)=>`<div class="step-time"><span><i style="background:${colors[name][i]}"></i>${x.label}</span><strong>${format(x.seconds)} s</strong></div>`).join('')+'</div>').join('')}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const name=b.dataset.method;document.querySelectorAll(`[data-method="${name}"]`).forEach(x=>x.classList.toggle('selected',x===b));$('#'+name+'-detail').textContent=explanations[name][Number(b.dataset.step)]});$('#breakdown').onchange=()=>{if(experiment)bars()};
fetch('data/timing.json').then(r=>{if(!r.ok)throw Error('Measured timings are not available yet.');return r.json()}).then(d=>{experiment=d;for(const name of ['classical','quantum']){const s=d.summary[name];$('#'+name+'-time').innerHTML=format(s.seconds)+'<small>s</small>';$('#'+name+'-label').textContent=format(s.seconds)+' s';$('#'+name+'-distance').textContent=Math.round(s.cost_km).toLocaleString('en-US')+' km';$('#'+name+'-gap').textContent=s.gap_percent.toFixed(2)+'%'}$('#measurement').textContent=`ACTUAL WALL TIME · MEDIAN OF ${d.repeats} RUNS`;const faster=d.ratio>=1?'Classical':'Quantum simulation';const ratio=d.ratio>=1?d.ratio:1/d.ratio;$('#finding').innerHTML=`On this instance, <strong>${faster} was ${ratio.toFixed(1)}× faster</strong>. This does not predict real QPU performance.`;$('#protocol').textContent=d.timing;$('#machine').textContent=`Environment: ${d.machine.system} ${d.machine.architecture} · Python ${d.machine.python} · Pulser ${d.machine.pulser} · QuTiP ${d.machine.qutip}. No MPS truncation. Run ID: ${d.instance}.`;bars()}).catch(e=>{$('#error').hidden=false;$('#error').textContent=e.message});
